&reftitle.changelog;





    &Version;
    &Description;





    8.1.0

     Ora restituisce un'istanza di PgSql\Lob;
     in precedenza veniva restituita una &resource;.


   &pgsql.changelog.connection-object;

  &reftitle.examples;



    Esempio di pg_lo_open


<?php
   $database = pg_connect("dbname=jacarta");
   pg_query($database, "begin");
   $oid = pg_lo_create($database);
   echo "$oid\n";
   $handle = pg_lo_open($database, $oid, "w");
   echo "$handle\n";
   pg_lo_write($handle, "dati del large object");
   pg_lo_close($handle);
   pg_query($database, "commit");
?>
